(function(root,factory){const api=factory();if(typeof module==='object')module.exports=api;else root.TripCore=api;})(globalThis,()=>{
 const costs=['tolls','scale','reefer','parking','defCost'];
 function number(v,label){if(typeof v!=='number'||!Number.isFinite(v)||v<0)throw Error('Enter a valid nonnegative '+label+'.');return v;}
 function lumper(t,final=false){const known=t.lumper!==null&&t.lumper!==''&&t.lumper!==undefined;const payer=t.lumperPayer||'unknown';if(!['unknown','company','driver','broker','none'].includes(payer))throw Error('Choose who paid the lumper.');if(known)number(t.lumper,'lumper cost');if(payer==='none'&&known&&t.lumper!==0)throw Error('No lumper needed must have a zero or blank cost.');const pending=payer!=='none'&&(!known||payer==='unknown');if(final&&pending)throw Error('Enter the final lumper amount and payer, or choose No lumper needed.');return {pending,charge:!pending&&payer!=='none'&&t.lumperDeduct?t.lumper:0};}
 function estimate(t,p){['pay','miles','deadhead','days','price','target','defGallons',...costs].forEach(k=>number(t[k],k));['mpg','driver','art','dispatch','factoring'].forEach(k=>number(p[k],k));if(t.miles<=0||t.days<=0||p.mpg<=0)throw Error('Loaded miles, days and MPG must be greater than zero.');const rate=(p.art+p.dispatch+p.factoring+(p.driverMode==='percent'?p.driver:0))/100;if(rate>=1)throw Error('Combined deductions must be below 100%.');const l=lumper(t),miles=t.miles+t.deadhead,gallons=miles/p.mpg,fuel=gallons*t.price,driver=p.driverMode==='percent'?t.pay*p.driver/100:miles*p.driver,deductions=t.pay*(p.art+p.dispatch+p.factoring)/100,base=fuel+(p.driverMode==='percent'?0:driver)+costs.reduce((n,k)=>n+t[k],0)+l.charge,cost=base+t.pay*rate,net=t.pay-cost;return {miles,gallons,fuel,driver,deductions,cost,net,netMile:net/miles,breakEven:base/(1-rate),targetRate:(base+t.target*miles)/(1-rate),lumperPending:l.pending,lumperCharge:l.charge};}
 function date(s){if(!/^\d{4}-\d{2}-\d{2}$/.test(s||''))throw Error('Enter a valid date.');const d=new Date(s+'T00:00:00Z');if(!Number.isFinite(+d)||d.toISOString().slice(0,10)!==s)throw Error('Enter a valid date.');return d;}
 function actual(t){date(t.completedAt);['pay','fuel','fuelGallons','defGallons','other',...costs].forEach(k=>number(t[k],k));const l=lumper(t,true),cost=t.fuel+t.other+costs.reduce((n,k)=>n+t[k],0)+l.charge;return {...t,cost,net:t.pay-cost};}
 function week(s){const start=date(s);start.setUTCDate(start.getUTCDate()-(start.getUTCDay()+6)%7);const days=Array.from({length:7},(_,i)=>new Date(+start+i*86400000).toISOString().slice(0,10));return {start:days[0],end:days[6],days};}
 function budgetFor(days,budgets){return days.reduce((sum,s)=>{const b=budgets.filter(b=>b.from<=s).sort((a,b)=>b.from.localeCompare(a.from))[0];if(!b)return sum;const d=date(s),count=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();return sum+['insurance','truckNote','tags','other','fees','maintenance','repairs','meals'].reduce((n,k)=>n+number(b[k]??0,k),0)/count;},0);}
 function weekly(trips,budgets,s,end){let w=week(s);if(end){const start=date(s),finish=date(end);if(finish<start)throw Error("End date must be on or after start date.");const count=(finish-start)/86400000+1;if(count>3660)throw Error("Choose a range of 10 years or less.");w={start:s,end,days:Array.from({length:count},(_,i)=>new Date(+start+i*86400000).toISOString().slice(0,10))};}const completed=trips.filter(t=>{try{actual(t.actual);return true}catch{return false}}),rows=completed.filter(t=>t.actual.completedAt>=w.start&&t.actual.completedAt<=w.end),gross=rows.reduce((n,t)=>n+t.actual.pay,0),expenses=rows.reduce((n,t)=>n+actual(t.actual).cost,0),business=budgetFor(w.days,budgets);return {...w,rows,pending:trips.length-completed.length,gross,expenses,business,earnings:gross-expenses,net:gross-expenses-business};}
 return {estimate,actual,lumper,week,weekly,budgetFor,date};
});
